"use client";

/**
 * "Type the slug to confirm" deletion form.
 *
 * Owner D. Private to the danger route. The confirmation is compared here for
 * immediate feedback and again on the server against the *stored* slug, so a
 * stale tab cannot delete a renamed organization.
 */

import { useActionState, useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import { deleteOrganizationAction } from "@/actions/organizations/delete-organization";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { Organization } from "@/types/organization";

export type DeleteOrganizationFormProps = {
  orgId: OrgId;
  slug: string;
};

type DeleteState = ActionResult<Organization> | null;

export function DeleteOrganizationForm(props: DeleteOrganizationFormProps) {
  const router = useRouter();
  const [confirmation, setConfirmation] = useState("");

  const [state, submit, pending] = useActionState<DeleteState, FormData>(
    async (_previous, formData) =>
      deleteOrganizationAction({
        orgId: props.orgId,
        confirmSlug: String(formData.get("confirmSlug") ?? ""),
      }),
    null,
  );

  useEffect(() => {
    if (state?.ok === true) {
      router.push("/orgs");
    }
  }, [state, router]);

  const matches = confirmation === props.slug;

  return (
    <form action={submit} className="space-y-3">
      <label htmlFor="confirmSlug" className="block text-sm text-rose-900">
        Type <code className="font-mono">{props.slug}</code> to confirm
      </label>
      <input
        id="confirmSlug"
        name="confirmSlug"
        value={confirmation}
        onChange={(event) => setConfirmation(event.target.value)}
        className="w-full rounded-md border border-rose-300 px-3 py-2 text-sm"
      />

      {state?.ok === false ? (
        <p role="alert" className="text-sm text-rose-700">
          {state.error.message}
        </p>
      ) : null}

      <button
        type="submit"
        disabled={!matches || pending}
        className="rounded-md bg-rose-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-50"
      >
        {pending ? "Deleting…" : "Delete organization"}
      </button>
    </form>
  );
}
/**
 * Destructive actions: transfer ownership, delete organization.
 *
 * Owner D. `org:delete` is owner-only in `ROLE_MATRIX`, so even an admin never
 * sees this page — the sub-nav filters it out and the page 404s if it is
 * reached directly.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { can } from "@/lib/permissions";
import { loadTenantContext } from "../../_lib/tenant-context";
import { DeleteOrganizationForm } from "./delete-organization-form";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Danger zone",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "org:delete", {
    kind: "organization",
    orgId: org.id,
  });
  if (!allowed) {
    notFound();
  }

  return (
    <div className="max-w-xl space-y-8">
      <header>
        <h1 className="text-xl font-semibold tracking-tight">Danger zone</h1>
        <p className="mt-1 text-sm text-slate-600">
          Only owners can see this page.
        </p>
      </header>

      <section className="rounded-md border border-rose-200 bg-rose-50 p-6">
        <h2 className="text-sm font-semibold text-rose-900">
          Delete this organization
        </h2>
        <p className="mt-2 text-sm text-rose-800">
          The organization is archived rather than erased — projects, issues and
          comments stop being reachable immediately, and the cleanup job removes
          them once the retention window expires. Everyone loses access at once.
        </p>

        <div className="mt-6">
          <DeleteOrganizationForm orgId={org.id} slug={org.slug} />
        </div>
      </section>

      <section className="rounded-md border border-slate-200 bg-white p-6">
        <h2 className="text-sm font-semibold">Transfer ownership</h2>
        <p className="mt-2 text-sm text-slate-600">
          Promote another member to owner from Settings → Members, then ask them
          to demote you. An organization must keep at least one owner at all
          times, which is why there is no one-click transfer here.
        </p>
      </section>
    </div>
  );
}
